'use strict';

const {test} = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const {dartPackages, requiredChecks, evaluateUpdate} = require('./dependency-policy.cjs');
const enable = require('./enable-dependabot-auto-merge.cjs');

const manifest = 'name: assiette\ndependencies:\n  http: ^1.6.0\n  geolocator: ^14.0.2\n';
const lock = (version = '1.6.0', native = '14.0.2') => `# Generated by pub
# See https://dart.dev/tools/pub/glossary#lockfile
packages:
  http:
    dependency: "direct main"
    description:
      name: http
      sha256: "${version}"
      url: "https://pub.dev"
    source: hosted
    version: "${version}"
  geolocator:
    dependency: "direct main"
    description:
      name: geolocator
      sha256: "native"
      url: "https://pub.dev"
    source: hosted
    version: "${native}"
sdks:
  dart: ">=3.8.0 <4.0.0"
`;
const update = overrides => ({
  files: [{filename: 'pubspec.lock', status: 'modified'}],
  beforeManifest: manifest, afterManifest: manifest,
  beforeLock: lock(), afterLock: lock('1.6.1'),
  ...overrides,
});

test('accepts a hosted Dart patch, including a manifest constraint bump', () => {
  assert.deepEqual(evaluateUpdate(update()), {eligible: true, updated: ['http']});
  assert.equal(evaluateUpdate(update({
    afterManifest: manifest.replace('^1.6.0', '^1.6.1'),
  })).eligible, true);
});

const rejected = {
  minor: {afterLock: lock('1.7.0')},
  major: {afterLock: lock('2.0.0')},
  downgrade: {afterLock: lock('1.5.9')},
  unchanged: {afterLock: lock()},
  prerelease: {afterLock: lock('1.6.1-dev.1')},
  native: {afterLock: lock('1.6.1', '14.0.3')},
  transitiveNative: {beforeLock: lock().replace('"direct main"', 'transitive'),
    afterLock: lock('1.6.1', '14.0.3').replace('"direct main"', 'transitive')},
  sdk: {afterLock: lock('1.6.1').replace('>=3.8.0', '>=3.12.0')},
  registry: {afterLock: lock('1.6.1').replace('https://pub.dev', 'https://example.com')},
  integrityOnly: {afterLock: lock().replace('sha256: "1.6.0"', 'sha256: "other"')},
  packageAdded: {afterLock: lock('1.6.1').replace('sdks:',
    '  extra:\n    source: hosted\n    version: "1.0.0"\nsdks:')},
  packageRemoved: {afterLock: lock('1.6.1').replace(/  geolocator:[\s\S]*?sdks:/, 'sdks:')},
  duplicatePackage: {afterLock: lock('1.6.1').replace('sdks:',
    '  http:\n    source: hosted\n    version: "1.6.1"\nsdks:')},
  malformedLock: {afterLock: 'not a pub lockfile'},
  nativeManifest: {afterManifest: manifest.replace('14.0.2', '14.0.3')},
  override: {afterManifest: manifest + 'dependency_overrides:\n  http: any\n'},
  loosenConstraint: {afterManifest: manifest.replace('^1.6.0', '1.6.1')},
  code: {files: [{filename: 'lib/main.dart', status: 'modified'}]},
  workflow: {files: [{filename: '.github/workflows/pull-request.yml', status: 'modified'}]},
  renamed: {files: [{filename: 'pubspec.lock', status: 'renamed'}]},
  empty: {files: []},
};
for (const [name, overrides] of Object.entries(rejected)) {
  test(`requires manual review: ${name}`, () => {
    assert.equal(evaluateUpdate(update(overrides)).eligible, false);
  });
}

test('the real repository lockfile is understood and the allowlist matches Dependabot', () => {
  const realLock = fs.readFileSync('pubspec.lock', 'utf8');
  const realManifest = fs.readFileSync('pubspec.yaml', 'utf8');
  const result = evaluateUpdate(update({beforeLock: realLock, afterLock: realLock,
    beforeManifest: realManifest, afterManifest: realManifest}));
  assert.equal(result.reason, 'No eligible patch update');
  const config = fs.readFileSync('.github/dependabot.yml', 'utf8');
  const group = config.split('dart-patches:')[1].split('update-types:')[0];
  const configured = [...group.matchAll(/^          - (\w+)$/gm)].map(match => match[1]);
  assert.deepEqual(new Set(configured), dartPackages);
  const protection = JSON.parse(fs.readFileSync('.github/main-protection.json', 'utf8'));
  assert.deepEqual(protection.required_status_checks.checks.map(check => check.context), requiredChecks);
  assert.equal(protection.required_status_checks.strict, true);
  assert.equal(protection.enforce_admins, true);
});

function fixture({conclusion = 'success', author = 'dependabot[bot]',
  protectedBranch = true, jobs = requiredChecks, changedHead = false,
  fork = false, workflow = '.github/workflows/pull-request.yml',
  native = false, protectedChecks = requiredChecks, checkApp = 15368} = {}) {
  const pr = {number: 1, node_id: 'PR_1', user: {login: author}, state: 'open', draft: false,
    base: {ref: 'main', sha: 'base', repo: {full_name: 'Gon3s/assiette'}},
    head: {ref: 'dependabot/pub/http-1.6.1', sha: 'head', repo: {full_name: 'Gon3s/assiette'}}};
  const mutations = [];
  let reads = 0;
  const github = {
    rest: {
      actions: {getWorkflow: async () => ({data: {path: workflow}}),
        listJobsForWorkflowRun: 'jobs'},
      pulls: {list: async () => ({data: [pr]}), listFiles: 'files',
        get: async () => ({data: ++reads > 1 && changedHead ?
          {...pr, head: {...pr.head, sha: 'new-head'}} : pr})},
      repos: {getBranch: async () => ({data: {protected: protectedBranch,
        protection: {required_status_checks: {checks: protectedChecks.map(context =>
          ({context, app_id: checkApp}))}}}}),
        getContent: async ({path, ref}) => ({data: {type: 'file', encoding: 'base64',
          content: Buffer.from(path === 'pubspec.yaml' ? manifest :
            lock(ref === 'base' ? '1.6.0' : '1.6.1', native && ref !== 'base' ?
              '14.0.3' : '14.0.2')).toString('base64')}})},
    },
    paginate: async method => method === 'jobs' ?
      jobs.map(name => ({name, conclusion: 'success'})) : update().files,
    graphql: async (...args) => mutations.push(args),
  };
  return {github, core: {info: () => {}}, mutations,
    context: {repo: {owner: 'Gon3s', repo: 'assiette'}, payload: {workflow_run: {
      id: 1, workflow_id: 2, event: 'pull_request', conclusion,
      head_repository: {full_name: fork ? 'other/assiette' : 'Gon3s/assiette'},
      head_sha: 'head', head_branch: pr.head.ref,
    }}}};
}

test('enables squash auto-merge only for the protected, tested bot commit', async () => {
  const f = fixture();
  await enable(f);
  assert.equal(f.mutations.length, 1);
  assert.deepEqual(f.mutations[0][1], {id: 'PR_1'});
});

for (const [name, options] of Object.entries({
  failed: {conclusion: 'failure'}, human: {author: 'Gon3s'},
  unprotected: {protectedBranch: false}, missingGate: {jobs: requiredChecks.slice(1)},
  stale: {changedHead: true}, fork: {fork: true},
  differentWorkflow: {workflow: '.github/workflows/other.yml'}, native: {native: true},
  missingRequiredChecks: {protectedChecks: []}, wrongCheckApp: {checkApp: 1},
})) {
  test(`never requests auto-merge: ${name}`, async () => {
    const f = fixture(options);
    await enable(f);
    assert.equal(f.mutations.length, 0);
  });
}
